#!/usr/bin/env python3
"""Wrap the npm package wasm-media-encoders (Ogg Vorbis only) as ONE classic script a file:// page can <script src>.

Chrome blocks fetch() of file:// URLs, and the package's UMD build fetches its .wasm from unpkg.com by
default. So ogg_vorbis_encoder.js carries the UMD build verbatim (it defines window.WasmMediaEncoder) plus
the libvorbis/libogg .wasm as base64 (window.WasmMediaEncoderOggWasmB64). AK.ogg (audio_kit.js) decodes
it, compiles it once and calls WasmMediaEncoder.createEncoder('audio/ogg', module): no network, ever.

  npm pack wasm-media-encoders@0.7.0 && tar xzf wasm-media-encoders-0.7.0.tgz
  python3 -I godot/tools/vendor/oggvorbis/pack.py package/

Python 3 standard library only. MP3 (LAME) is left out on purpose.
"""
import base64
import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

XIPH_BSD = """Copyright (c) 2002-2020 Xiph.org Foundation

Redistribution and use in source and binary forms, with or without
modification, are permitted provided that the following conditions
are met:

- Redistributions of source code must retain the above copyright
notice, this list of conditions and the following disclaimer.

- Redistributions in binary form must reproduce the above copyright
notice, this list of conditions and the following disclaimer in the
documentation and/or other materials provided with the distribution.

- Neither the name of the Xiph.org Foundation nor the names of its
contributors may be used to endorse or promote products derived from
this software without specific prior written permission.

THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS
``AS IS'' AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT
LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR
A PARTICULAR PURPOSE ARE DISCLAIMED.  IN NO EVENT SHALL THE FOUNDATION
OR CONTRIBUTORS BE LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL,
SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT
LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR SERVICES; LOSS OF USE,
DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER CAUSED AND ON ANY
THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT
(INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE
OF THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE."""


def main() -> int:
    if len(sys.argv) != 2:
        print(__doc__)
        return 2
    pkg = Path(sys.argv[1]).resolve()
    meta = json.loads((pkg / "package.json").read_text())
    umd = (pkg / "dist/umd/WasmMediaEncoder.min.js").read_text().strip()
    wasm = (pkg / "wasm/ogg.wasm").read_bytes()
    mit = (pkg / "LICENSE").read_text().strip()
    if "unpkg.com" not in umd or "createEncoder" not in umd:
        print("unexpected UMD build — check the package version")
        return 1
    sha = lambda b: hashlib.sha256(b).hexdigest()
    head = "\n".join([
        "/* ogg_vorbis_encoder.js — Ogg Vorbis encoder for the file:// tool pages (no network, no build step).",
        " *",
        f" * {meta['name']}@{meta['version']} (https://github.com/arseneyr/wasm-media-encoders): the UMD build",
        " * dist/umd/WasmMediaEncoder.min.js verbatim, then wasm/ogg.wasm as base64. Generated by pack.py in this",
        " * folder — do not edit by hand. Used through AK.ogg in audio_kit.js.",
        f" *   UMD  sha256 {sha(umd.encode())}",
        f" *   wasm sha256 {sha(wasm)} ({len(wasm)} bytes)",
        " *",
        " * ── wasm-media-encoders: MIT License ──",
        *[" * " + l if l else " *" for l in mit.splitlines()],
        " *",
        " * ── ogg.wasm contains libvorbis and libogg (Xiph.org): BSD 3-Clause License ──",
        *[" * " + l if l else " *" for l in XIPH_BSD.splitlines()],
        " */",
    ])
    b64 = base64.b64encode(wasm).decode()
    body = (f"{head}\n{umd}\n"
            "/* the wasm that createEncoder('audio/ogg', bytes) instantiates (AK.ogg decodes + compiles it once) */\n"
            f"var WasmMediaEncoderOggWasmB64 = \"{b64}\";\n")
    out = HERE / "ogg_vorbis_encoder.js"
    out.write_text(body)
    print(f"wrote {out} ({len(body)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
